from playwright.sync_api import sync_playwright
from h import *
OVER="""(()=>{const W=innerWidth,out=[];document.querySelectorAll('body *').forEach(e=>{if(e.closest('iframe,.tf,.ws-panel:not(.x),.ws-insp:not(.x)')&&!e.closest('.sheet-open .ws-panel')&&!e.closest('.insp-open .ws-insp'))return;const cs=getComputedStyle(e);if(cs.visibility==='hidden'||cs.display==='none'||cs.position==='fixed'&&e.closest('.dlg-wrap')===null&&false)return;const r=e.getBoundingClientRect();if(r.width&&r.height&&(r.right>W+1||r.left<-1)&&!e.closest('.skip,.stepper,.tabs,.sel-tb,.editor,.hl,.tabbody pre,.toast,.swatches')){out.push(e.tagName+'.'+String(e.className).slice(0,30)+' '+Math.round(r.left)+'-'+Math.round(r.right))}});return out.slice(0,6)})()"""
def check(pg,label):
    sw=pg.evaluate('document.documentElement.scrollWidth'); iw=pg.evaluate('innerWidth'); off=pg.evaluate(OVER)
    ok(f'{label}: no horizontal overflow', sw<=iw+1 and not off, [sw,iw,off])
    back=pg.locator('.appbar .back'); bb=back.bounding_box()
    ok(f'{label}: Back visible & touch-sized', bb and bb['x']>=0 and bb['width']>=40 and bb['height']>=40, bb)
import sys
W,H=(int(sys.argv[1]),int(sys.argv[2])) if len(sys.argv)>2 else (390,844)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':W,'height':H},has_touch=True,is_mobile=True,device_scale_factor=2,accept_downloads=True); pg=ctx.new_page()
    errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(APP); pg.wait_for_timeout(900); check(pg,'landing'); pg.screenshot(path=f'm_landing_{W}.png')
    ok('landing: Back disabled (no previous step)', pg.is_disabled('.appbar .back'))
    pg.tap('.l-cta [data-act=startnew]'); pg.wait_for_timeout(500); check(pg,'style step')
    pg.tap('.sysopt:nth-child(2)'); pg.fill('#wiz-name','Phone test'); pg.tap('.stepbar [data-act=wiznext]'); pg.wait_for_timeout(700); check(pg,'template step'); pg.screenshot(path=f'm_tpl_{W}.png')
    sb=pg.locator('.stepbar').bounding_box(); ok('template: step bar fully on-screen', sb['y']+sb['height']<=H+1, sb)
    pg.tap('.gcard:has-text("Digital Playground") [data-act=tplpick]'); pg.wait_for_timeout(300)
    pg.tap('.stepbar [data-act=next]'); pg.wait_for_timeout(600); check(pg,'info step'); pg.screenshot(path=f'm_info_{W}.png')
    pg.fill('[data-bind="person/name"]','Sam Mobile'); pg.wait_for_timeout(300)
    ok('info: mobile Preview button available', pg.is_visible('.appbar [data-act=previewdlg]'))
    pg.tap('.appbar [data-act=previewdlg]'); pg.wait_for_timeout(1200); ok('preview dialog shows data', pg.frame_locator('.dlg iframe').locator('.name').inner_text()=='Sam Mobile'); pg.tap('.dlg [data-dlg=c]'); pg.wait_for_timeout(300)
    pg.tap('.appbar .back'); pg.wait_for_timeout(500); ok('back -> template (tpl kept)', pg.evaluate('location.hash')=='#/new/template' and pg.evaluate('PV.S.project.design.template')=='digital-playground')
    pg.tap('.stepbar [data-act=next]'); pg.wait_for_timeout(500); ok('forward data preserved', pg.input_value('[data-bind="person/name"]')=='Sam Mobile')
    pg.tap('.stepbar [data-act=next]'); pg.wait_for_timeout(600); check(pg,'sections step')
    pg.tap('.stepbar [data-act=next]'); pg.wait_for_timeout(1200); check(pg,'customize step'); pg.screenshot(path=f'm_custom_{W}.png')
    pg.tap('.bn [data-sheet=design]'); pg.wait_for_timeout(600); pg.screenshot(path=f'm_sheet_{W}.png')
    r=pg.locator('#wspanel').bounding_box(); bn=pg.locator('.bn').bounding_box(); ok('design sheet sits above bottom nav (no overlap)', r['y']+r['height']<=bn['y']+2 and r['y']>=0, [r,bn])
    ok('sheet tabs reachable', pg.locator('#wspanel .tab').count()==3)
    pg.tap('#wspanel [data-act=accgroup][data-key=type]'); pg.wait_for_timeout(300)
    pg.select_option('#wspanel [data-bind="design.type.heading"]','Fredoka'); pg.wait_for_timeout(400); ok('mobile design control edits model', pg.evaluate('PV.S.project.design.type.heading')=='Fredoka')
    pg.tap('#wspanel [data-act=closesheet]'); pg.wait_for_timeout(500); ok('sheet closes', pg.evaluate('!document.querySelector(".ws").classList.contains("sheet-open")'))
    pg.tap('.nextbtn'); pg.wait_for_timeout(1500); check(pg,'editor'); ok('editor route', pg.evaluate('location.hash')=='#/editor')
    pg.evaluate("document.querySelector('#prevhost iframe').contentWindow") 
    f=fr(pg); f.locator('.name').tap(); pg.wait_for_timeout(700)
    ok('tap selects element', pg.evaluate('PV.S.ui.selected')=='person/name')
    tb=pg.locator('.sel-tb').bounding_box(); bnb=pg.locator('.bn').bounding_box(); ok('toolbar docked above bottom nav', tb and tb['y']+tb['height']<=bnb['y']+2, [tb,bnb]); pg.screenshot(path=f'm_sel_{W}.png')
    pg.tap('.sel-tb [data-act=tb-insp]'); pg.wait_for_timeout(600); ok('inspector sheet opens', pg.is_visible('#wsinsp [data-bind="person/name"]'))
    pg.fill('#wsinsp [data-bind="person/name"]','Sam M.'); pg.wait_for_timeout(600); ok('mobile edit -> model + preview', pg.evaluate('PV.S.project.person.name')=='Sam M.' and fr(pg).locator('.name').inner_text()=='Sam M.')
    pg.screenshot(path=f'm_insp_{W}.png')
    pg.tap('#wsinsp [data-act=tb-x]'); pg.wait_for_timeout(400)
    pg.tap('.bn [data-sheet=content]'); pg.wait_for_timeout(500); ok('content sheet', pg.is_visible('#wspanel .tabbody')); 
    pg.evaluate('history.back()'); pg.wait_for_timeout(700); ok('browser Back closes sheet first', pg.evaluate('!document.querySelector(".ws").classList.contains("sheet-open")') and pg.evaluate('location.hash')=='#/editor', pg.evaluate('location.hash'))
    pg.tap('.bn [data-sheet=miy]') if pg.locator('.bn [data-sheet=miy]').count() else pg.tap('.miy-tool'); pg.wait_for_timeout(500)
    pg.tap('.preset:has-text("More Bold")'); pg.wait_for_timeout(1200); ok('mobile MIY variations', pg.evaluate('PV.S.variations.length')==3); pg.screenshot(path=f'm_miy_{W}.png')
    pg.tap('.miy-actions [data-act=miydiscard]'); pg.wait_for_timeout(400); pg.tap('#wspanel [data-act=closesheet]'); pg.wait_for_timeout(400)
    pg.tap('.bn [data-to="/editor/code"]'); pg.wait_for_timeout(1500); check(pg,'code'); ok('code route', pg.evaluate('location.hash')=='#/editor/code'); pg.screenshot(path=f'm_code_{W}.png')
    pg.tap('.seg-m [data-v=prev]'); pg.wait_for_timeout(500); ok('code/preview switcher', pg.is_visible('.codeprev') )
    pg.tap('.seg-m [data-v=code]'); pg.wait_for_timeout(300)
    pg.tap('.appbar .back'); pg.wait_for_timeout(600); ok('code back -> editor', pg.evaluate('location.hash')=='#/editor')
    pg.tap('.bn [data-to="/editor/export"]'); pg.wait_for_timeout(1000); check(pg,'export'); pg.screenshot(path=f'm_export_{W}.png')
    with pg.expect_download() as dl: pg.tap('[data-act=dlhtml]')
    html=open(dl.value.path(),encoding='utf8').read(); ok('mobile: finished HTML downloaded with edits', 'Sam M.' in html and html.startswith('<!DOCTYPE'))
    pg.tap('.stepbar [data-act=finish]'); pg.wait_for_timeout(600); ok('finish -> projects', pg.evaluate('location.hash')=='#/projects'); check(pg,'projects')
    print('errs',errs); b.close()
bad=[r for r in res if not r[1]]; print(len(res)-len(bad),'passed',len(bad),'failed')
